mapper.select:
SELECT A.ATTENDANCE_ID AS attendanceId, A.STUDENT_ID AS studentId, S.EDU_ID AS eduId, A.ATTEND_DATE AS attendDate, A.STATUS AS status, A.MESSAGE AS message, A.CREATED_AT AS createdAt, A.UPDATED_AT AS updatedAt FROM ATTENDANCE A LEFT JOIN STUDENTS S ON A.STUDENT_ID = S.STUDENT_ID
S.DEL_YN = 'N'
AND A.STUDENT_ID = #{studentId}
AND S.EDU_ID = #{eduId}
